DO $dairy$
DECLARE payload jsonb := $payload$[{"language": "es", "slug": "mozzarella-casera", "public_path": "/mozzarella-casera", "title": "Mozzarella casera con leche, cuajo y ácido cítrico", "excerpt": "Haz mozzarella fresca en casa con cuajo y ácido cítrico. Seis pasos con fotos, leche adecuada, temperaturas de cuajado e hilado y consejos si no estira.", "summary": "Esta mozzarella fresca se hace con leche pasteurizada no UHT, ácido cítrico alimentario y cuajo. Rinde unos 400–500 g con 4 litros. Necesitas termómetro, báscula, jeringa graduada y guantes alimentarios resistentes al calor. Reserva unos 90 minutos; la leche puede variar el resultado.", "content_html": "<p>Esta mozzarella fresca se hace con leche pasteurizada no UHT, ácido cítrico alimentario y cuajo. Rinde unos 400–500 g con 4 litros. Necesitas termómetro, báscula, jeringa graduada y guantes alimentarios resistentes al calor. Reserva unos 90 minutos; la leche puede variar el resultado.</p>", "notes": "<h3>Consejos y conservación</h3><p>Consume en 2–3 días. Si no estira aun estando caliente, puede fallar la leche o la acidez; no añadas ácido a ciegas ni sigas amasando hasta secar. El limón no sustituye con precisión el ácido cítrico. No intercambies pastillas por ml sin leer el fabricante. Sin prueba de cocina propia. Contiene leche. Usa utensilios limpios y desinfectados y conserva a 4 °C o menos. No es una conserva para guardar a temperatura ambiente.</p><ul><li><a href=\"https://ucanr.edu/site/master-food-preserver-program-san-diego-county/fresh-mozzarella-cheese\">UC Master Food Preservers — fresh mozzarella</a></li><li><a href=\"https://cheesemaking.com/products/30-minute-mozzarella-recipe\">New England Cheesemaking — mozzarella technique</a></li></ul>", "ingredients": [{"name": "leche entera pasteurizada no UHT, preferiblemente no homogeneizada", "amount": "4000", "unit": "ml"}, {"name": "ácido cítrico alimentario", "amount": "7", "unit": "g"}, {"name": "cuajo líquido alimentario, aproximadamente 200 IMCU/ml", "amount": "1", "unit": "ml"}, {"name": "agua potable fría sin cloro para las dos disoluciones", "amount": "310", "unit": "ml"}, {"name": "agua potable para el baño caliente y enfriado, más hielo", "amount": "2000", "unit": "ml"}, {"name": "sal fina", "amount": "8", "unit": "g"}], "steps": [{"title": "Acidifica y añade cuajo", "content": "Disuelve el ácido en 250 ml del agua fría y mézclalo con la leche fría. Calienta a 32 °C. Retira del fuego. Diluye el cuajo en los otros 60 ml de agua, añade y mezcla suavemente 30 segundos. La dosis corresponde a la fuerza indicada; revisa la etiqueta.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-01.webp", "image_alt": "Acidifica y añade cuajo — Mozzarella casera con leche, cuajo y ácido cítrico"}, {"title": "Cuaja y corta", "content": "Tapa y deja 10 minutos sin mover. Cuando el corte se separe limpiamente, corta cuadrados de 2,5 cm y espera 5 minutos. Si sigue muy blanda, espera hasta 20 minutos más; no rompas una cuajada líquida.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-02.webp", "image_alt": "Cuaja y corta — Mozzarella casera con leche, cuajo y ácido cítrico"}, {"title": "Calienta y escurre", "content": "Calienta despacio a 42–43 °C, moviendo los trozos con delicadeza. Retira y remueve 2 minutos. Pasa a un colador con espumadera, escurre 5 minutos y reparte la sal. No exprimas enérgicamente.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-03.webp", "image_alt": "Calienta y escurre — Mozzarella casera con leche, cuajo y ácido cítrico"}, {"title": "Calienta para hilar", "content": "Usa parte del agua en un baño a unos 80 °C. Con espumadera y guantes térmicos alimentarios, sumerge porciones hasta que la cuajada alcance aproximadamente 57–60 °C y se una. Estira suavemente y pliega 2–3 veces hasta alisar. No metas las manos desnudas en el agua.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-04.webp", "image_alt": "Calienta para hilar — Mozzarella casera con leche, cuajo y ácido cítrico"}, {"title": "Forma y enfría", "content": "Recoge los bordes hacia dentro para formar bolas, sin amasar demasiado. Pasa al resto del agua con hielo unos 10 minutos para fijar la forma. Usa más agua si hace falta; es agua de proceso, no rendimiento de la receta.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-05.webp", "image_alt": "Forma y enfría — Mozzarella casera con leche, cuajo y ácido cítrico"}, {"title": "Guarda y sirve", "content": "Escurre y guarda en recipiente cerrado en la nevera, al menos 20 minutos antes de cortar. Sirve fresca o escurre bien para pizza. La textura casera puede ser más húmeda que la mozzarella industrial para rallar.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-06.webp", "image_alt": "Guarda y sirve — Mozzarella casera con leche, cuajo y ácido cítrico"}], "category": "Guarniciones", "course": "Guarniciones", "cuisine": "Internacional", "difficulty": "Fácil", "prep_time_minutes": 25, "cook_time_minutes": 20, "total_time_minutes": 90, "servings": 9, "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/mozzarella-casera/portada.webp", "alt": "Mozzarella casera con leche, cuajo y ácido cítrico"}], "video_urls": [], "keywords": ["Mozzarella casera con leche, cuajo y ácido cítrico"], "nutrition": {"calories": 140, "protein_g": 9, "carbs_g": 1, "fat_g": 11, "serving_size": "1 de 9 porciones, unos 50 g", "estimated": true, "note": "Estimación por porción; el rendimiento, la humedad y la marca cambian los valores.", "source": "Generic fresh whole-milk mozzarella proxy; editorial estimate", "method": "Finished-cheese proxy per 100 g: 280 kcal, 18 g protein, 2 g carbohydrate, 22 g fat. Multiply by 0.5 for a 50 g portion, assuming 450 g yield. Whey and bath excluded; no measured nutrient retention. Actual yield 400–500 g."}, "seo": {"title": "Mozzarella casera con leche, cuajo y ácido cítrico", "description": "Haz mozzarella fresca en casa con cuajo y ácido cítrico. Seis pasos con fotos, leche adecuada, temperaturas de cuajado e hilado y consejos si no estira.", "author": "Néstor Bastidas", "image_alt": "Mozzarella casera con leche, cuajo y ácido cítrico", "image_variants": ["https://manualdecocina.com/recetas/mozzarella-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-16x9.webp"], "faq": [{"q": "¿Se hace solo con vinagre?", "a": "Esta ficha usa cuajo y ácido cítrico. Cortar leche con vinagre no garantiza una mozzarella que hile."}, {"q": "¿Por qué se rompe al estirar?", "a": "Puede estar fría o tener acidez inadecuada. Recalienta suavemente una porción; si sigue rompiéndose, no fuerces todo el lote."}], "additional_time_minutes": 45}, "published": false, "editorial_status": "ready"}, {"language": "en", "slug": "homemade-fresh-mozzarella", "public_path": "/en/homemade-fresh-mozzarella", "title": "Homemade mozzarella with rennet and citric acid", "excerpt": "Make fresh mozzarella with rennet and citric acid. Six photo steps explain milk choice, setting and stretching temperatures, cooling and troubleshooting.", "summary": "Use pasteurized non-UHT milk, food-grade citric acid and rennet. Four litres yield roughly 400–500 g. You need a thermometer, scale, graduated syringe and food-safe heat-resistant gloves. Allow about 90 minutes; milk affects the result.", "content_html": "<p>Use pasteurized non-UHT milk, food-grade citric acid and rennet. Four litres yield roughly 400–500 g. You need a thermometer, scale, graduated syringe and food-safe heat-resistant gloves. Allow about 90 minutes; milk affects the result.</p>", "notes": "<h3>Tips and storage</h3><p>Use within 2–3 days. Failure to stretch despite sufficient heat may mean unsuitable milk or acidity. Do not add acid blindly or keep kneading until dry. Lemon juice is not a precise citric-acid substitute. Do not equate tablets with ml without label instructions. Not kitchen-tested. Contains milk. Use clean, sanitized equipment and refrigerate at 4 °C or below. This is not a shelf-stable canned product.</p><ul><li><a href=\"https://ucanr.edu/site/master-food-preserver-program-san-diego-county/fresh-mozzarella-cheese\">UC Master Food Preservers — fresh mozzarella</a></li><li><a href=\"https://cheesemaking.com/products/30-minute-mozzarella-recipe\">New England Cheesemaking — mozzarella technique</a></li></ul>", "ingredients": [{"name": "pasteurized whole milk, not UHT, preferably non-homogenized", "amount": "4000", "unit": "ml"}, {"name": "food-grade citric acid", "amount": "7", "unit": "g"}, {"name": "food-grade liquid rennet, approximately 200 IMCU/ml", "amount": "1", "unit": "ml"}, {"name": "cold chlorine-free drinking water for both solutions", "amount": "310", "unit": "ml"}, {"name": "drinking water for heating and cooling baths, plus ice", "amount": "2000", "unit": "ml"}, {"name": "fine salt", "amount": "8", "unit": "g"}], "steps": [{"title": "Acidify and add rennet", "content": "Dissolve citric acid in 250 ml cold water and mix into cold milk. Heat to 32 °C and remove from heat. Dilute rennet in the remaining 60 ml water, add and stir gently for 30 seconds. Dose applies to the stated strength; check the label.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-01.webp", "image_alt": "Acidify and add rennet — Homemade mozzarella with rennet and citric acid"}, {"title": "Set and cut", "content": "Cover and rest undisturbed for 10 minutes. Once there is a clean break, cut 2.5 cm squares and wait 5 minutes. If too soft, allow up to 20 more minutes; do not break up liquid curd.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-02.webp", "image_alt": "Set and cut — Homemade mozzarella with rennet and citric acid"}, {"title": "Heat and drain", "content": "Warm slowly to 42–43 °C, moving curds gently. Remove from heat and stir for 2 minutes. Ladle into a strainer, drain 5 minutes and distribute the salt. Avoid hard squeezing.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-03.webp", "image_alt": "Heat and drain — Homemade mozzarella with rennet and citric acid"}, {"title": "Warm and stretch", "content": "Heat part of the bath water to about 80 °C. Using a slotted spoon and food-safe heat-resistant gloves, immerse portions until curd reaches about 57–60 °C and comes together. Gently stretch and fold 2–3 times until smooth. Never put bare hands in hot water.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-04.webp", "image_alt": "Warm and stretch — Homemade mozzarella with rennet and citric acid"}, {"title": "Shape and cool", "content": "Tuck edges underneath to make balls without overworking. Cool in the remaining water with ice for about 10 minutes to set the shape. Add bath water as needed; process water is not recipe yield.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-05.webp", "image_alt": "Shape and cool — Homemade mozzarella with rennet and citric acid"}, {"title": "Store and serve", "content": "Drain and refrigerate in a covered container for at least 20 minutes before slicing. Serve fresh or drain well for pizza. Homemade mozzarella can be wetter than commercial shredding cheese.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-06.webp", "image_alt": "Store and serve — Homemade mozzarella with rennet and citric acid"}], "category": "Side dishes", "course": "Side dishes", "cuisine": "International", "difficulty": "Easy", "prep_time_minutes": 25, "cook_time_minutes": 20, "total_time_minutes": 90, "servings": 9, "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/mozzarella-casera/portada.webp", "alt": "Homemade mozzarella with rennet and citric acid"}], "video_urls": [], "keywords": ["Homemade mozzarella with rennet and citric acid"], "nutrition": {"calories": 140, "protein_g": 9, "carbs_g": 1, "fat_g": 11, "serving_size": "1 of 9 servings, about 50 g", "estimated": true, "note": "Estimated per serving; yield, moisture and brands affect the values.", "source": "Generic fresh whole-milk mozzarella proxy; editorial estimate", "method": "Finished-cheese proxy per 100 g: 280 kcal, 18 g protein, 2 g carbohydrate, 22 g fat. Multiply by 0.5 for a 50 g portion, assuming 450 g yield. Whey and bath excluded; no measured nutrient retention. Actual yield 400–500 g."}, "seo": {"title": "Homemade mozzarella with rennet and citric acid", "description": "Make fresh mozzarella with rennet and citric acid. Six photo steps explain milk choice, setting and stretching temperatures, cooling and troubleshooting.", "author": "Néstor Bastidas", "image_alt": "Homemade mozzarella with rennet and citric acid", "image_variants": ["https://manualdecocina.com/recetas/mozzarella-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-16x9.webp"], "faq": [{"q": "Can I use vinegar alone?", "a": "This recipe uses rennet and citric acid. Vinegar-set milk does not reliably produce stretching mozzarella."}, {"q": "Why does it tear?", "a": "It may be cold or have unsuitable acidity. Gently rewarm one portion; if it still tears, do not force the entire batch."}], "additional_time_minutes": 45}, "published": false, "editorial_status": "ready"}, {"language": "de", "slug": "mozzarella-selber-machen", "public_path": "/de/mozzarella-selber-machen", "title": "Mozzarella mit Lab und Zitronensäure selber machen", "excerpt": "Frischen Mozzarella mit Lab und Zitronensäure herstellen. Sechs Schrittfotos erklären Milchwahl, Temperaturen beim Gerinnen und Ziehen sowie das Abkühlen.", "summary": "Verwende pasteurisierte Milch, keine H-Milch, lebensmittelechte Zitronensäure und Lab. Vier Liter ergeben etwa 400–500 g. Thermometer, Waage, graduierte Spritze und lebensmittelechte Hitzeschutzhandschuhe bereitlegen. Plane rund 90 Minuten ein; die Milch beeinflusst das Ergebnis.", "content_html": "<p>Verwende pasteurisierte Milch, keine H-Milch, lebensmittelechte Zitronensäure und Lab. Vier Liter ergeben etwa 400–500 g. Thermometer, Waage, graduierte Spritze und lebensmittelechte Hitzeschutzhandschuhe bereitlegen. Plane rund 90 Minuten ein; die Milch beeinflusst das Ergebnis.</p>", "notes": "<h3>Tipps und Aufbewahrung</h3><p>In 2–3 Tagen verbrauchen. Zieht warmer Bruch nicht, können Milch oder Säure ungeeignet sein. Nicht blind Säure zugeben oder trocken kneten. Zitronensaft ersetzt die Säure nicht präzise. Tabletten nicht ohne Herstellerangabe in ml umrechnen. Nicht küchenerprobt. Enthält Milch. Saubere, desinfizierte Geräte verwenden und bei höchstens 4 °C lagern. Dies ist keine ungekühlt haltbare Konserve.</p><ul><li><a href=\"https://ucanr.edu/site/master-food-preserver-program-san-diego-county/fresh-mozzarella-cheese\">UC Master Food Preservers — fresh mozzarella</a></li><li><a href=\"https://cheesemaking.com/products/30-minute-mozzarella-recipe\">New England Cheesemaking — mozzarella technique</a></li></ul>", "ingredients": [{"name": "pasteurisierte Vollmilch, keine H-Milch, möglichst nicht homogenisiert", "amount": "4000", "unit": "ml"}, {"name": "lebensmittelechte Zitronensäure", "amount": "7", "unit": "g"}, {"name": "lebensmittelechtes flüssiges Lab, etwa 200 IMCU/ml", "amount": "1", "unit": "ml"}, {"name": "kaltes chlorfreies Trinkwasser für beide Lösungen", "amount": "310", "unit": "ml"}, {"name": "Trinkwasser für heißes und kaltes Wasserbad, zusätzlich Eis", "amount": "2000", "unit": "ml"}, {"name": "feines Salz", "amount": "8", "unit": "g"}], "steps": [{"title": "Säuern und Lab zugeben", "content": "Zitronensäure in 250 ml kaltem Wasser lösen und in die kalte Milch mischen. Auf 32 °C erwärmen und vom Herd nehmen. Lab in den übrigen 60 ml Wasser verdünnen, zugeben und 30 Sekunden sanft rühren. Dosierung an der angegebenen Stärke und Herstellerangabe prüfen.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-01.webp", "image_alt": "Säuern und Lab zugeben — Mozzarella mit Lab und Zitronensäure selber machen"}, {"title": "Gerinnen und schneiden", "content": "Abdecken und 10 Minuten ungestört stehen lassen. Bei sauberem Bruch in 2,5 cm große Quadrate schneiden und 5 Minuten warten. Zu weichen Bruch bis zu 20 Minuten länger ruhen lassen; flüssige Masse nicht zerschneiden.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-02.webp", "image_alt": "Gerinnen und schneiden — Mozzarella mit Lab und Zitronensäure selber machen"}, {"title": "Erwärmen und abtropfen", "content": "Langsam auf 42–43 °C erwärmen und Bruch behutsam bewegen. Vom Herd nehmen und 2 Minuten rühren. Mit Schaumlöffel ins Sieb geben, 5 Minuten abtropfen lassen und Salz verteilen. Nicht kräftig ausdrücken.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-03.webp", "image_alt": "Erwärmen und abtropfen — Mozzarella mit Lab und Zitronensäure selber machen"}, {"title": "Zum Ziehen erwärmen", "content": "Einen Teil des Badewassers auf etwa 80 °C erhitzen. Portionen mit Schaumlöffel und geeigneten Hitzeschutzhandschuhen eintauchen, bis der Bruch etwa 57–60 °C erreicht und zusammenhält. Sanft 2–3-mal ziehen und falten. Nie bloße Hände ins heiße Wasser tauchen.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-04.webp", "image_alt": "Zum Ziehen erwärmen — Mozzarella mit Lab und Zitronensäure selber machen"}, {"title": "Formen und abkühlen", "content": "Ränder nach innen schlagen und ohne starkes Kneten Kugeln formen. In das übrige Wasser mit Eis legen und etwa 10 Minuten abkühlen. Bei Bedarf mehr Badewasser nehmen; es zählt nicht zur Ausbeute.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-05.webp", "image_alt": "Formen und abkühlen — Mozzarella mit Lab und Zitronensäure selber machen"}, {"title": "Lagern und servieren", "content": "Abtropfen und in einer geschlossenen Dose mindestens 20 Minuten kühlen, dann schneiden. Frisch essen oder für Pizza gut abtropfen lassen. Hausgemachter Mozzarella kann feuchter sein als Reibemozzarella.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-06.webp", "image_alt": "Lagern und servieren — Mozzarella mit Lab und Zitronensäure selber machen"}], "category": "Beilagen", "course": "Beilagen", "cuisine": "International", "difficulty": "Einfach", "prep_time_minutes": 25, "cook_time_minutes": 20, "total_time_minutes": 90, "servings": 9, "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/mozzarella-casera/portada.webp", "alt": "Mozzarella mit Lab und Zitronensäure selber machen"}], "video_urls": [], "keywords": ["Mozzarella mit Lab und Zitronensäure selber machen"], "nutrition": {"calories": 140, "protein_g": 9, "carbs_g": 1, "fat_g": 11, "serving_size": "1 von 9 Portionen, etwa 50 g", "estimated": true, "note": "Schätzung pro Portion; Ausbeute, Feuchtigkeit und Produkte beeinflussen die Werte.", "source": "Generic fresh whole-milk mozzarella proxy; editorial estimate", "method": "Finished-cheese proxy per 100 g: 280 kcal, 18 g protein, 2 g carbohydrate, 22 g fat. Multiply by 0.5 for a 50 g portion, assuming 450 g yield. Whey and bath excluded; no measured nutrient retention. Actual yield 400–500 g."}, "seo": {"title": "Mozzarella mit Lab und Zitronensäure selber machen", "description": "Frischen Mozzarella mit Lab und Zitronensäure herstellen. Sechs Schrittfotos erklären Milchwahl, Temperaturen beim Gerinnen und Ziehen sowie das Abkühlen.", "author": "Néstor Bastidas", "image_alt": "Mozzarella mit Lab und Zitronensäure selber machen", "image_variants": ["https://manualdecocina.com/recetas/mozzarella-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-16x9.webp"], "faq": [{"q": "Geht es nur mit Essig?", "a": "Hier werden Lab und Zitronensäure verwendet. Essig allein liefert nicht zuverlässig ziehfähigen Mozzarella."}, {"q": "Warum reißt der Käse?", "a": "Er kann zu kalt sein oder eine ungeeignete Säure haben. Eine Portion vorsichtig nachwärmen und nicht die ganze Menge mit Gewalt ziehen."}], "additional_time_minutes": 45}, "published": false, "editorial_status": "ready"}, {"language": "fr", "slug": "mozzarella-fraiche-maison", "public_path": "/fr/mozzarella-fraiche-maison", "title": "Mozzarella maison à la présure et à l'acide citrique", "excerpt": "Faites une mozzarella fraîche à la présure et à l'acide citrique. Six étapes en photos expliquent le lait adapté, le caillage, le filage et le refroidissement.", "summary": "Utilisez du lait pasteurisé non UHT, de l'acide citrique alimentaire et de la présure. Quatre litres donnent environ 400–500 g. Prévoyez thermomètre, balance, seringue graduée et gants alimentaires résistants à la chaleur. Comptez environ 90 minutes ; le lait influence le résultat.", "content_html": "<p>Utilisez du lait pasteurisé non UHT, de l&#x27;acide citrique alimentaire et de la présure. Quatre litres donnent environ 400–500 g. Prévoyez thermomètre, balance, seringue graduée et gants alimentaires résistants à la chaleur. Comptez environ 90 minutes ; le lait influence le résultat.</p>", "notes": "<h3>Conseils et conservation</h3><p>Consommez sous 2–3 jours. Si elle ne file pas malgré la chaleur, lait ou acidité peuvent être en cause. N&#x27;ajoutez pas d&#x27;acide au hasard et ne pétrissez pas jusqu&#x27;à dessécher. Le citron ne remplace pas précisément l&#x27;acide citrique. Vérifiez l&#x27;équivalence des comprimés. Non testée en cuisine. Contient du lait. Utilisez du matériel propre et désinfecté et conservez à 4 °C maximum. Cette préparation ne se conserve pas à température ambiante.</p><ul><li><a href=\"https://ucanr.edu/site/master-food-preserver-program-san-diego-county/fresh-mozzarella-cheese\">UC Master Food Preservers — fresh mozzarella</a></li><li><a href=\"https://cheesemaking.com/products/30-minute-mozzarella-recipe\">New England Cheesemaking — mozzarella technique</a></li></ul>", "ingredients": [{"name": "lait entier pasteurisé non UHT, de préférence non homogénéisé", "amount": "4000", "unit": "ml"}, {"name": "acide citrique alimentaire", "amount": "7", "unit": "g"}, {"name": "présure liquide alimentaire, environ 200 IMCU/ml", "amount": "1", "unit": "ml"}, {"name": "eau potable froide sans chlore pour les deux solutions", "amount": "310", "unit": "ml"}, {"name": "eau potable pour bains chaud et froid, plus glaçons", "amount": "2000", "unit": "ml"}, {"name": "sel fin", "amount": "8", "unit": "g"}], "steps": [{"title": "Acidifiez et ajoutez la présure", "content": "Dissolvez l'acide dans 250 ml d'eau froide et mélangez au lait froid. Chauffez à 32 °C et retirez du feu. Diluez la présure dans les 60 ml restants, ajoutez et remuez doucement 30 secondes. Vérifiez la concentration et l'étiquette du fabricant.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-01.webp", "image_alt": "Acidifiez et ajoutez la présure — Mozzarella maison à la présure et à l'acide citrique"}, {"title": "Faites prendre et coupez", "content": "Couvrez et attendez 10 minutes sans bouger. Quand la cassure est nette, découpez des carrés de 2,5 cm et reposez 5 minutes. Si trop mou, attendez jusqu'à 20 minutes de plus ; ne découpez pas une masse liquide.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-02.webp", "image_alt": "Faites prendre et coupez — Mozzarella maison à la présure et à l'acide citrique"}, {"title": "Chauffez et égouttez", "content": "Portez doucement à 42–43 °C en déplaçant délicatement les morceaux. Retirez du feu et remuez 2 minutes. Transférez à l'écumoire dans une passoire, égouttez 5 minutes et répartissez le sel. Ne pressez pas fortement.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-03.webp", "image_alt": "Chauffez et égouttez — Mozzarella maison à la présure et à l'acide citrique"}, {"title": "Réchauffez pour filer", "content": "Chauffez une partie de l'eau à environ 80 °C. Avec écumoire et gants thermiques alimentaires, immergez des portions jusqu'à environ 57–60 °C au cœur et jusqu'à cohésion. Étirez et repliez doucement 2–3 fois. Jamais de mains nues dans l'eau chaude.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-04.webp", "image_alt": "Réchauffez pour filer — Mozzarella maison à la présure et à l'acide citrique"}, {"title": "Formez et refroidissez", "content": "Rentrez les bords pour former des boules sans trop pétrir. Placez dans l'eau restante avec des glaçons environ 10 minutes. Ajoutez de l'eau de bain si nécessaire ; elle ne compte pas dans le rendement.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-05.webp", "image_alt": "Formez et refroidissez — Mozzarella maison à la présure et à l'acide citrique"}, {"title": "Conservez et servez", "content": "Égouttez et réfrigérez en boîte fermée au moins 20 minutes avant de couper. Servez frais ou égouttez bien pour la pizza. La mozzarella maison peut être plus humide qu'un fromage industriel à râper.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-06.webp", "image_alt": "Conservez et servez — Mozzarella maison à la présure et à l'acide citrique"}], "category": "Accompagnements", "course": "Accompagnements", "cuisine": "Internationale", "difficulty": "Facile", "prep_time_minutes": 25, "cook_time_minutes": 20, "total_time_minutes": 90, "servings": 9, "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/mozzarella-casera/portada.webp", "alt": "Mozzarella maison à la présure et à l'acide citrique"}], "video_urls": [], "keywords": ["Mozzarella maison à la présure et à l'acide citrique"], "nutrition": {"calories": 140, "protein_g": 9, "carbs_g": 1, "fat_g": 11, "serving_size": "1 des 9 portions, environ 50 g", "estimated": true, "note": "Estimation par portion ; rendement, humidité et marques modifient les valeurs.", "source": "Generic fresh whole-milk mozzarella proxy; editorial estimate", "method": "Finished-cheese proxy per 100 g: 280 kcal, 18 g protein, 2 g carbohydrate, 22 g fat. Multiply by 0.5 for a 50 g portion, assuming 450 g yield. Whey and bath excluded; no measured nutrient retention. Actual yield 400–500 g."}, "seo": {"title": "Mozzarella maison à la présure et à l'acide citrique", "description": "Faites une mozzarella fraîche à la présure et à l'acide citrique. Six étapes en photos expliquent le lait adapté, le caillage, le filage et le refroidissement.", "author": "Néstor Bastidas", "image_alt": "Mozzarella maison à la présure et à l'acide citrique", "image_variants": ["https://manualdecocina.com/recetas/mozzarella-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-16x9.webp"], "faq": [{"q": "Peut-on utiliser seulement du vinaigre ?", "a": "Cette recette emploie présure et acide citrique. Le vinaigre seul ne garantit pas une mozzarella filante."}, {"q": "Pourquoi se déchire-t-elle ?", "a": "Le caillé peut être froid ou mal acidifié. Réchauffez doucement une portion ; si elle se déchire encore, ne forcez pas le lot."}], "additional_time_minutes": 45}, "published": false, "editorial_status": "ready"}, {"language": "it", "slug": "mozzarella-fatta-in-casa", "public_path": "/it/mozzarella-fatta-in-casa", "title": "Mozzarella fatta in casa con caglio e acido citrico", "excerpt": "Prepara mozzarella fresca con caglio e acido citrico. Sei passaggi fotografati spiegano latte adatto, temperature di coagulazione e filatura e raffreddamento.", "summary": "Usa latte pastorizzato non UHT, acido citrico alimentare e caglio. Quattro litri rendono circa 400–500 g. Servono termometro, bilancia, siringa graduata e guanti alimentari resistenti al calore. Riserva circa 90 minuti; il tipo di latte influenza la riuscita.", "content_html": "<p>Usa latte pastorizzato non UHT, acido citrico alimentare e caglio. Quattro litri rendono circa 400–500 g. Servono termometro, bilancia, siringa graduata e guanti alimentari resistenti al calore. Riserva circa 90 minuti; il tipo di latte influenza la riuscita.</p>", "notes": "<h3>Consigli e conservazione</h3><p>Consuma entro 2–3 giorni. Se non fila anche calda, possono influire latte e acidità. Non aggiungere acido alla cieca né lavorare fino ad asciugarla. Il limone non sostituisce precisamente l&#x27;acido citrico. Non convertire compresse in ml senza istruzioni. Non testata in cucina. Contiene latte. Usa utensili puliti e igienizzati e conserva a 4 °C o meno. Non è una conserva da tenere a temperatura ambiente.</p><ul><li><a href=\"https://ucanr.edu/site/master-food-preserver-program-san-diego-county/fresh-mozzarella-cheese\">UC Master Food Preservers — fresh mozzarella</a></li><li><a href=\"https://cheesemaking.com/products/30-minute-mozzarella-recipe\">New England Cheesemaking — mozzarella technique</a></li></ul>", "ingredients": [{"name": "latte intero pastorizzato non UHT, preferibilmente non omogeneizzato", "amount": "4000", "unit": "ml"}, {"name": "acido citrico alimentare", "amount": "7", "unit": "g"}, {"name": "caglio liquido alimentare, circa 200 IMCU/ml", "amount": "1", "unit": "ml"}, {"name": "acqua potabile fredda senza cloro per le due soluzioni", "amount": "310", "unit": "ml"}, {"name": "acqua potabile per bagno caldo e freddo, più ghiaccio", "amount": "2000", "unit": "ml"}, {"name": "sale fino", "amount": "8", "unit": "g"}], "steps": [{"title": "Acidifica e aggiungi il caglio", "content": "Sciogli l'acido in 250 ml d'acqua fredda e mescola nel latte freddo. Porta a 32 °C e togli dal fuoco. Diluisci il caglio nei 60 ml rimasti, aggiungi e mescola piano 30 secondi. La dose vale per la forza indicata: controlla l'etichetta.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-01.webp", "image_alt": "Acidifica e aggiungi il caglio — Mozzarella fatta in casa con caglio e acido citrico"}, {"title": "Fai cagliare e taglia", "content": "Copri e lascia immobile 10 minuti. Con rottura netta, taglia quadrati di 2,5 cm e aspetta 5 minuti. Se troppo morbida, attendi fino a 20 minuti in più; non rompere una cagliata liquida.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-02.webp", "image_alt": "Fai cagliare e taglia — Mozzarella fatta in casa con caglio e acido citrico"}, {"title": "Scalda e scola", "content": "Porta lentamente a 42–43 °C muovendo delicatamente i pezzi. Togli dal fuoco e mescola 2 minuti. Passa con schiumarola nel colino, scola 5 minuti e distribuisci il sale. Non strizzare forte.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-03.webp", "image_alt": "Scalda e scola — Mozzarella fatta in casa con caglio e acido citrico"}, {"title": "Scalda per filare", "content": "Porta parte dell'acqua a circa 80 °C. Con schiumarola e guanti termici alimentari immergi porzioni finché la cagliata raggiunge circa 57–60 °C e si unisce. Tira e ripiega dolcemente 2–3 volte. Non immergere mani nude nell'acqua calda.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-04.webp", "image_alt": "Scalda per filare — Mozzarella fatta in casa con caglio e acido citrico"}, {"title": "Forma e raffredda", "content": "Ripiega i bordi sotto per formare palline senza lavorare troppo. Raffredda nell'acqua rimasta con ghiaccio per circa 10 minuti. Aggiungi acqua per il bagno se serve; non rientra nella resa.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-05.webp", "image_alt": "Forma e raffredda — Mozzarella fatta in casa con caglio e acido citrico"}, {"title": "Conserva e servi", "content": "Scola e refrigera in recipiente chiuso per almeno 20 minuti prima di tagliare. Servi fresca o scola bene per la pizza. Può essere più umida della mozzarella industriale da grattugiare.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-06.webp", "image_alt": "Conserva e servi — Mozzarella fatta in casa con caglio e acido citrico"}], "category": "Contorni", "course": "Contorni", "cuisine": "Internazionale", "difficulty": "Facile", "prep_time_minutes": 25, "cook_time_minutes": 20, "total_time_minutes": 90, "servings": 9, "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/mozzarella-casera/portada.webp", "alt": "Mozzarella fatta in casa con caglio e acido citrico"}], "video_urls": [], "keywords": ["Mozzarella fatta in casa con caglio e acido citrico"], "nutrition": {"calories": 140, "protein_g": 9, "carbs_g": 1, "fat_g": 11, "serving_size": "1 di 9 porzioni, circa 50 g", "estimated": true, "note": "Stima per porzione; resa, umidità e prodotti possono cambiare i valori.", "source": "Generic fresh whole-milk mozzarella proxy; editorial estimate", "method": "Finished-cheese proxy per 100 g: 280 kcal, 18 g protein, 2 g carbohydrate, 22 g fat. Multiply by 0.5 for a 50 g portion, assuming 450 g yield. Whey and bath excluded; no measured nutrient retention. Actual yield 400–500 g."}, "seo": {"title": "Mozzarella fatta in casa con caglio e acido citrico", "description": "Prepara mozzarella fresca con caglio e acido citrico. Sei passaggi fotografati spiegano latte adatto, temperature di coagulazione e filatura e raffreddamento.", "author": "Néstor Bastidas", "image_alt": "Mozzarella fatta in casa con caglio e acido citrico", "image_variants": ["https://manualdecocina.com/recetas/mozzarella-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-16x9.webp"], "faq": [{"q": "Basta l'aceto?", "a": "Qui servono caglio e acido citrico. Latte coagulato con solo aceto non garantisce mozzarella filante."}, {"q": "Perché si spezza?", "a": "Può essere fredda o avere acidità inadatta. Riscalda piano una porzione; se si rompe ancora, non forzare tutto il lotto."}], "additional_time_minutes": 45}, "published": false, "editorial_status": "ready"}, {"language": "ja", "slug": "homemade-fresh-mozzarella", "public_path": "/ja/homemade-fresh-mozzarella", "title": "レンネットとクエン酸で作る自家製モッツァレラ", "excerpt": "殺菌牛乳、食品用クエン酸、レンネットで作るモッツァレラ。6工程の写真で牛乳の選び方、凝固、加熱、引き伸ばし、冷却を解説。伸びないときの確認点も紹介します。", "summary": "超高温殺菌ではない殺菌牛乳、食品用クエン酸、レンネットを使います。4 Lで約400〜500 g。温度計、はかり、目盛り付きシリンジ、食品用耐熱手袋が必要です。約90分を見込みます。牛乳によって仕上がりが変わります。", "content_html": "<p>超高温殺菌ではない殺菌牛乳、食品用クエン酸、レンネットを使います。4 Lで約400〜500 g。温度計、はかり、目盛り付きシリンジ、食品用耐熱手袋が必要です。約90分を見込みます。牛乳によって仕上がりが変わります。</p>", "notes": "<h3>コツと保存</h3><p>2〜3日以内に食べます。温かくても伸びない場合は牛乳や酸度が原因のことがあります。むやみに酸を足したり、乾くまで練ったりしません。レモン汁はクエン酸の正確な代用品ではありません。錠剤の換算は製品指示で確認します。調理試験は行っていません。 乳を含みます。清潔に洗浄・消毒した器具を使い、4 ℃以下で冷蔵してください。常温保存用の瓶詰めではありません。</p><ul><li><a href=\"https://ucanr.edu/site/master-food-preserver-program-san-diego-county/fresh-mozzarella-cheese\">UC Master Food Preservers — fresh mozzarella</a></li><li><a href=\"https://cheesemaking.com/products/30-minute-mozzarella-recipe\">New England Cheesemaking — mozzarella technique</a></li></ul>", "ingredients": [{"name": "超高温殺菌ではない殺菌済み全乳、できればノンホモ牛乳", "amount": "4000", "unit": "ml"}, {"name": "食品用クエン酸", "amount": "7", "unit": "g"}, {"name": "食品用液体レンネット、約200 IMCU/ml", "amount": "1", "unit": "ml"}, {"name": "2つの溶液用の冷たい塩素を含まない飲用水", "amount": "310", "unit": "ml"}, {"name": "加熱・冷却用の飲用水、別途氷", "amount": "2000", "unit": "ml"}, {"name": "細かい塩", "amount": "8", "unit": "g"}], "steps": [{"title": "酸と凝乳剤を加える", "content": "クエン酸を冷水250 mlに溶かして冷たい牛乳に混ぜ、32 ℃まで温めて火を止めます。残りの水60 mlでレンネットを薄め、加えて30秒静かに混ぜます。量は記載濃度用なので製品表示を確認します。", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-01.webp", "image_alt": "酸と凝乳剤を加える — レンネットとクエン酸で作る自家製モッツァレラ"}, {"title": "固めて切る", "content": "ふたをして10分動かしません。きれいに切り分かれたら2.5 cm角に切り、5分休ませます。柔らかすぎるときはさらに最大20分待ちます。液状のまま切り混ぜません。", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-02.webp", "image_alt": "固めて切る — レンネットとクエン酸で作る自家製モッツァレラ"}, {"title": "温めて水切りする", "content": "静かに動かしながら42〜43 ℃まで温めます。火を止めて2分混ぜ、穴あきお玉でざるに移します。5分水切りして塩を分け入れます。強く絞りません。", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-03.webp", "image_alt": "温めて水切りする — レンネットとクエン酸で作る自家製モッツァレラ"}, {"title": "温めて伸ばす", "content": "湯の一部を約80 ℃にします。食品用耐熱手袋と穴あきお玉を使い、少量ずつ浸して中心が約57〜60 ℃になり、まとまるまで温めます。2〜3回優しく伸ばして折り、滑らかにします。素手で湯に触れないでください。", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-04.webp", "image_alt": "温めて伸ばす — レンネットとクエン酸で作る自家製モッツァレラ"}, {"title": "丸めて冷やす", "content": "縁を内側に折り込み、練りすぎず丸めます。残りの水に氷を入れ、約10分冷やして形を整えます。必要なら水を足します。工程用の水は出来上がり量に含めません。", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-05.webp", "image_alt": "丸めて冷やす — レンネットとクエン酸で作る自家製モッツァレラ"}, {"title": "保存して切る", "content": "水を切り、ふた付き容器で最低20分冷蔵してから切ります。そのまま食べるか、ピザにはよく水切りして使います。市販の細切り用より水分が多くなります。", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-06.webp", "image_alt": "保存して切る — レンネットとクエン酸で作る自家製モッツァレラ"}], "category": "付け合わせ", "course": "付け合わせ", "cuisine": "各国料理", "difficulty": "簡単", "prep_time_minutes": 25, "cook_time_minutes": 20, "total_time_minutes": 90, "servings": 9, "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/mozzarella-casera/portada.webp", "alt": "レンネットとクエン酸で作る自家製モッツァレラ"}], "video_urls": [], "keywords": ["レンネットとクエン酸で作る自家製モッツァレラ"], "nutrition": {"calories": 140, "protein_g": 9, "carbs_g": 1, "fat_g": 11, "serving_size": "9食分の1、約50 g", "estimated": true, "note": "1食分の推定値です。出来上がり量、水分、製品により異なります。", "source": "Generic fresh whole-milk mozzarella proxy; editorial estimate", "method": "Finished-cheese proxy per 100 g: 280 kcal, 18 g protein, 2 g carbohydrate, 22 g fat. Multiply by 0.5 for a 50 g portion, assuming 450 g yield. Whey and bath excluded; no measured nutrient retention. Actual yield 400–500 g."}, "seo": {"title": "レンネットとクエン酸で作る自家製モッツァレラ", "description": "殺菌牛乳、食品用クエン酸、レンネットで作るモッツァレラ。6工程の写真で牛乳の選び方、凝固、加熱、引き伸ばし、冷却を解説。伸びないときの確認点も紹介します。", "author": "Néstor Bastidas", "image_alt": "レンネットとクエン酸で作る自家製モッツァレラ", "image_variants": ["https://manualdecocina.com/recetas/mozzarella-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-16x9.webp"], "faq": [{"q": "酢だけで作れますか。", "a": "このレシピはレンネットとクエン酸を使います。酢だけで固めても、伸びるモッツァレラになるとは限りません。"}, {"q": "伸ばすと切れるのはなぜですか。", "a": "温度が低いか酸度が合わないことがあります。少量を温め直し、それでも切れるなら全量を無理に引っ張りません。"}], "additional_time_minutes": 45}, "published": false, "editorial_status": "ready"}, {"language": "pt", "slug": "mozzarella-caseira", "public_path": "/pt/mozzarella-caseira", "title": "Mozzarella caseira com coalho e ácido cítrico", "excerpt": "Faça mozzarella fresca com coalho e ácido cítrico. Seis etapas com fotos explicam leite adequado, temperaturas de coagulação e filagem e resfriamento.", "summary": "Use leite pasteurizado não UHT, ácido cítrico alimentício e coalho. Quatro litros rendem cerca de 400–500 g. Tenha termômetro, balança, seringa graduada e luvas alimentícias resistentes ao calor. Reserve cerca de 90 minutos; o leite influencia o resultado.", "content_html": "<p>Use leite pasteurizado não UHT, ácido cítrico alimentício e coalho. Quatro litros rendem cerca de 400–500 g. Tenha termômetro, balança, seringa graduada e luvas alimentícias resistentes ao calor. Reserve cerca de 90 minutos; o leite influencia o resultado.</p>", "notes": "<h3>Dicas e conservação</h3><p>Consuma em 2–3 dias. Se não esticar mesmo quente, leite ou acidez podem ser inadequados. Não acrescente ácido às cegas nem sove até secar. Limão não substitui precisamente o ácido cítrico. Não converta comprimidos em ml sem instruções. Sem teste de cozinha próprio. Contém leite. Use utensílios limpos e higienizados e conserve a 4 °C ou menos. Não é uma conserva para guardar à temperatura ambiente.</p><ul><li><a href=\"https://ucanr.edu/site/master-food-preserver-program-san-diego-county/fresh-mozzarella-cheese\">UC Master Food Preservers — fresh mozzarella</a></li><li><a href=\"https://cheesemaking.com/products/30-minute-mozzarella-recipe\">New England Cheesemaking — mozzarella technique</a></li></ul>", "ingredients": [{"name": "leite integral pasteurizado não UHT, preferencialmente não homogeneizado", "amount": "4000", "unit": "ml"}, {"name": "ácido cítrico alimentício", "amount": "7", "unit": "g"}, {"name": "coalho líquido alimentício, aproximadamente 200 IMCU/ml", "amount": "1", "unit": "ml"}, {"name": "água potável fria sem cloro para as duas soluções", "amount": "310", "unit": "ml"}, {"name": "água potável para banho quente e frio, mais gelo", "amount": "2000", "unit": "ml"}, {"name": "sal fino", "amount": "8", "unit": "g"}], "steps": [{"title": "Acidifique e adicione coalho", "content": "Dissolva o ácido em 250 ml de água fria e misture no leite frio. Aqueça a 32 °C e retire do fogo. Dilua o coalho nos outros 60 ml, adicione e mexa delicadamente 30 segundos. A dose vale para a concentração indicada; confira o rótulo.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-01.webp", "image_alt": "Acidifique e adicione coalho — Mozzarella caseira com coalho e ácido cítrico"}, {"title": "Coalhe e corte", "content": "Tampe e deixe imóvel 10 minutos. Quando o corte for limpo, faça quadrados de 2,5 cm e espere 5 minutos. Se estiver mole, aguarde até mais 20 minutos; não quebre coalhada líquida.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-02.webp", "image_alt": "Coalhe e corte — Mozzarella caseira com coalho e ácido cítrico"}, {"title": "Aqueça e escorra", "content": "Aqueça lentamente a 42–43 °C, movendo os pedaços com cuidado. Retire e mexa 2 minutos. Passe com escumadeira para peneira, escorra 5 minutos e distribua o sal. Não esprema com força.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-03.webp", "image_alt": "Aqueça e escorra — Mozzarella caseira com coalho e ácido cítrico"}, {"title": "Aqueça para filar", "content": "Aqueça parte da água a cerca de 80 °C. Com escumadeira e luvas térmicas alimentícias, mergulhe porções até a massa atingir aproximadamente 57–60 °C e se unir. Estique e dobre suavemente 2–3 vezes até alisar. Nunca mergulhe mãos nuas na água quente.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-04.webp", "image_alt": "Aqueça para filar — Mozzarella caseira com coalho e ácido cítrico"}, {"title": "Modele e esfrie", "content": "Dobre as bordas para dentro formando bolas, sem sovar demais. Resfrie no restante da água com gelo por cerca de 10 minutos. Acrescente água para o banho se necessário; ela não conta no rendimento.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-05.webp", "image_alt": "Modele e esfrie — Mozzarella caseira com coalho e ácido cítrico"}, {"title": "Guarde e sirva", "content": "Escorra e refrigere em recipiente fechado por pelo menos 20 minutos antes de cortar. Sirva fresca ou escorra bem para pizza. Pode ficar mais úmida que mozzarella industrial para ralar.", "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/paso-06.webp", "image_alt": "Guarde e sirva — Mozzarella caseira com coalho e ácido cítrico"}], "category": "Acompanhamentos", "course": "Acompanhamentos", "cuisine": "Internacional", "difficulty": "Fácil", "prep_time_minutes": 25, "cook_time_minutes": 20, "total_time_minutes": 90, "servings": 9, "image_url": "https://manualdecocina.com/recetas/mozzarella-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/mozzarella-casera/portada.webp", "alt": "Mozzarella caseira com coalho e ácido cítrico"}], "video_urls": [], "keywords": ["Mozzarella caseira com coalho e ácido cítrico"], "nutrition": {"calories": 140, "protein_g": 9, "carbs_g": 1, "fat_g": 11, "serving_size": "1 de 9 porções, cerca de 50 g", "estimated": true, "note": "Estimativa por porção; rendimento, umidade e marcas alteram os valores.", "source": "Generic fresh whole-milk mozzarella proxy; editorial estimate", "method": "Finished-cheese proxy per 100 g: 280 kcal, 18 g protein, 2 g carbohydrate, 22 g fat. Multiply by 0.5 for a 50 g portion, assuming 450 g yield. Whey and bath excluded; no measured nutrient retention. Actual yield 400–500 g."}, "seo": {"title": "Mozzarella caseira com coalho e ácido cítrico", "description": "Faça mozzarella fresca com coalho e ácido cítrico. Seis etapas com fotos explicam leite adequado, temperaturas de coagulação e filagem e resfriamento.", "author": "Néstor Bastidas", "image_alt": "Mozzarella caseira com coalho e ácido cítrico", "image_variants": ["https://manualdecocina.com/recetas/mozzarella-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/mozzarella-casera/portada-16x9.webp"], "faq": [{"q": "Dá para fazer só com vinagre?", "a": "Esta receita usa coalho e ácido cítrico. Leite cortado apenas com vinagre não garante mozzarella que file."}, {"q": "Por que rasga ao esticar?", "a": "Pode estar fria ou com acidez inadequada. Reaqueça uma porção com cuidado; se ainda rasgar, não force o lote todo."}], "additional_time_minutes": 45}, "published": false, "editorial_status": "ready"}]$payload$::jsonb;
foods jsonb := $foods$[{"slug": "acido-citrico", "name": "Ácido cítrico alimentario"}, {"slug": "cuajo", "name": "Cuajo"}]$foods$::jsonb;
aliases jsonb := $aliases$[{"slug": "leche", "alias": "leche entera pasteurizada no UHT, preferiblemente no homogeneizada"}, {"slug": "acido-citrico", "alias": "ácido cítrico alimentario"}, {"slug": "cuajo", "alias": "cuajo líquido alimentario, aproximadamente 200 IMCU/ml"}, {"slug": "agua", "alias": "agua potable fría sin cloro para las dos disoluciones"}, {"slug": "agua", "alias": "agua potable para el baño caliente y enfriado, más hielo"}, {"slug": "sal", "alias": "sal fina"}]$aliases$::jsonb;
x jsonb; a jsonb; v public.recipes; made public.recipes; source_id uuid; group_id uuid;
BEGIN
PERFORM set_config('request.jwt.claim.sub','2caf0bab-d7e8-4d52-9910-d79799c27072',true);
IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin context missing'; END IF;
IF jsonb_array_length(payload)<>7 THEN RAISE EXCEPTION 'Need seven languages'; END IF;
IF EXISTS(SELECT 1 FROM public.recipes r JOIN jsonb_array_elements(payload) e ON r.public_path=e->>'public_path' OR (r.language=e->>'language' AND r.slug=e->>'slug')) THEN RAISE EXCEPTION 'Recipe already exists'; END IF;
IF EXISTS(SELECT 1 FROM public.content_pages p JOIN jsonb_array_elements(payload) e ON p.public_path=e->>'public_path') OR EXISTS(SELECT 1 FROM public.content_redirects r JOIN jsonb_array_elements(payload) e ON r.source_path=e->>'public_path') THEN RAISE EXCEPTION 'Route collision'; END IF;
FOR a IN SELECT value FROM jsonb_array_elements(foods) LOOP
 INSERT INTO public.ingredients(slug,name,normalized_name,description,status,searchable,indexable)
 SELECT a->>'slug',a->>'name',lower(a->>'name'),'Ingrediente para elaboraciones lácteas domésticas.','canonical',true,false WHERE NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug');
END LOOP;
FOR a IN SELECT value FROM jsonb_array_elements(aliases) LOOP
 IF NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical') THEN RAISE EXCEPTION 'Missing ingredient %',a; END IF;
 IF EXISTS(SELECT 1 FROM public.ingredient_aliases ia JOIN public.ingredients i ON i.id=ia.ingredient_id WHERE lower(trim(ia.alias))=lower(trim(a->>'alias')) AND i.slug<>a->>'slug' AND i.status='canonical') THEN RAISE EXCEPTION 'Alias collision %',a; END IF;
 INSERT INTO public.ingredient_aliases(ingredient_id,alias,normalized_alias) SELECT id,a->>'alias',lower(a->>'alias') FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical' ON CONFLICT(ingredient_id,normalized_alias) DO NOTHING;
END LOOP;
FOR x IN SELECT value FROM jsonb_array_elements(payload) LOOP
 v:=jsonb_populate_record(NULL::public.recipes,x);
 IF v.language='es' THEN
  made:=public.create_recipe(v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
  source_id:=made.id;group_id:=made.recipe_group_id;
 ELSE
  made:=public.create_recipe_translation(source_id,v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
 END IF;
 UPDATE public.recipes SET content_html=v.content_html,summary=v.summary,notes=v.notes,difficulty=v.difficulty,course=v.course,cuisine=v.cuisine,total_time_minutes=v.total_time_minutes,keywords=v.keywords,nutrition=v.nutrition,gallery=v.gallery,video_urls=v.video_urls,seo=v.seo,editorial_status='ready',ready_at=now() WHERE id=made.id;
END LOOP;
IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=group_id)<>7 THEN RAISE EXCEPTION 'Incomplete group'; END IF;
IF (SELECT count(*) FROM public.recipe_ingredients WHERE recipe_id=source_id)<>6 OR EXISTS(SELECT 1 FROM public.recipe_ingredient_pending WHERE recipe_id=source_id) THEN RAISE EXCEPTION 'Unresolved ingredients'; END IF;
FOR v IN SELECT * FROM public.recipes WHERE recipe_group_id=group_id LOOP
 PERFORM public.update_recipe(v.id,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,true);
 UPDATE public.recipes SET editorial_status='published' WHERE id=v.id;
END LOOP;
END $dairy$;
SELECT language,public_path,published FROM public.recipes WHERE recipe_group_id=(SELECT recipe_group_id FROM public.recipes WHERE language='es' AND slug='mozzarella-casera') ORDER BY language;
